// Generated by the Salvo compiler: the process scheduler — asynchronous
// effect handlers' runtime. The Kotlin mirror of the Rust backend's
// scheduler module; the semantics are decided in CONCURRENCY.md ("The
// first pass") and SUPERVISION.md and must stay identical on both
// backends: run-to-completion activations on pool threads, per-process
// bounded queues (bound explicit at spawn; a full queue blocks the
// sender), reply tokens with reserved capacity (a reply never blocks and
// never counts against the bound), the gate (at most one outstanding per
// process; while gated only the awaited reply is delivered), death = a
// faulted activation caught at the dispatch boundary (sends and replies
// to the dead are silent no-ops; watchers are notified with the reason),
// and the idle-with-parked-gates report. Pool threads are daemon threads:
// the program ends when main returns.
package salvo

import kotlin.concurrent.withLock

/** A process body: state plus one entry point per kind of delivery. */
interface SalvoProcess {
    /** A user message (a `send fn` invocation). */
    fun handle(ctx: SalvoCtx, msg: Any?)

    /** A reply delivery: the slot names the parked continuation. */
    fun resume(ctx: SalvoCtx, slot: Long, value: Any?)
}

/** Passed to every activation: the process's own identity. */
class SalvoCtx(val pid: Int)

private sealed class SalvoEntry {
    class User(val msg: Any?) : SalvoEntry()

    class Reply(val slot: Long, val value: Any?) : SalvoEntry()
}

private class SalvoProcState(val bound: Int, val pool: Int, var body: SalvoProcess?) {
    val queue = ArrayDeque<SalvoEntry>()
    var userLen = 0
    var gate: Long? = null
    var running = false
    var dead = false
    val watchers = mutableListOf<SalvoReply>()
}

private class SalvoWaiterState {
    var value: Any? = null
    var filled = false
}

/**
 * The scheduler: one shared lock (its own monitor) over all state, pool
 * worker threads, and the waiter bridge for `main`.
 */
object SalvoSched {
    private val lock = java.util.concurrent.locks.ReentrantLock()
    private val cv = lock.newCondition()
    private val procs = mutableListOf<SalvoProcState>()
    private val waiters = mutableListOf<SalvoWaiterState>()
    private var pools = 0
    private var nextSlot = 0L
    private var active = 0

    /** Creates a pool of [n] daemon worker threads and answers its id. */
    fun pool(n: Int): Int {
        val id = lock.withLock { pools++ }
        repeat(n) {
            Thread { worker(id) }.apply {
                isDaemon = true
                start()
            }
        }
        return id
    }

    /** Spawns a process on a pool. The queue bound is explicit and required. */
    fun spawn(pool: Int, bound: Int, body: SalvoProcess): Int =
        lock.withLock {
            procs.add(SalvoProcState(bound, pool, body))
            procs.size - 1
        }

    /**
     * Sends a user message. Blocks while the target's queue is full; a
     * send to a dead process is a silent no-op.
     */
    fun send(pid: Int, msg: Any?) {
        lock.withLock {
            while (!procs[pid].dead && procs[pid].userLen >= procs[pid].bound) {
                cv.await()
            }
            if (procs[pid].dead) {
                return
            }
            procs[pid].queue.addLast(SalvoEntry.User(msg))
            procs[pid].userLen += 1
            cv.signalAll()
        }
    }

    /** Mints a reply token targeting a process's parked continuation. */
    fun mint(pid: Int): SalvoReply =
        lock.withLock {
            nextSlot += 1
            SalvoReply(SalvoTargetProc(pid), nextSlot)
        }

    /**
     * Mints a *gated* reply token: until it is delivered, the process
     * serves nothing else. At most one gate may be outstanding — a second
     * is a fault in the calling activation.
     */
    fun mintGated(pid: Int): SalvoReply =
        lock.withLock {
            check(procs[pid].gate == null) { "a gated continuation is already outstanding" }
            nextSlot += 1
            procs[pid].gate = nextSlot
            SalvoReply(SalvoTargetProc(pid), nextSlot)
        }

    /**
     * Registers a death watch: [onExit] is sent the reason when the
     * process dies. Watching an already-dead process answers immediately.
     */
    fun watch(pid: Int, onExit: SalvoReply) {
        lock.withLock {
            if (procs[pid].dead) {
                deliverReply(onExit, "fault")
                cv.signalAll()
            } else {
                procs[pid].watchers.add(onExit)
            }
        }
    }

    /** A waiter: the `waitfor` bridge. Answers (token, waiter id). */
    fun waiter(): Pair<SalvoReply, Int> =
        lock.withLock {
            waiters.add(SalvoWaiterState())
            nextSlot += 1
            Pair(SalvoReply(SalvoTargetWaiter(waiters.size - 1), nextSlot), waiters.size - 1)
        }

    /**
     * Blocks the calling (main) thread until the waiter's token is sent,
     * and answers the value. If the scheduler is idle and can never
     * fulfil it, reports the deadlock instead of hanging.
     */
    fun awaitReply(wid: Int): Any? {
        lock.withLock {
            while (true) {
                if (waiters[wid].filled) {
                    waiters[wid].filled = false
                    return waiters[wid].value
                }
                if (idle()) {
                    reportDeadlock()
                }
                cv.await()
            }
        }
    }

    internal fun sendReply(reply: SalvoReply, value: Any?) {
        lock.withLock {
            deliverReply(reply, value)
            cv.signalAll()
        }
    }

    /** Delivery under the lock: reserved capacity, no-op to the dead. */
    private fun deliverReply(reply: SalvoReply, value: Any?) {
        when (val target = reply.target) {
            is SalvoTargetWaiter -> {
                waiters[target.wid].value = value
                waiters[target.wid].filled = true
            }
            is SalvoTargetProc -> {
                if (procs[target.pid].dead) {
                    return
                }
                procs[target.pid].queue.addLast(SalvoEntry.Reply(reply.slot, value))
            }
        }
    }

    /** The first deliverable entry for a process, honouring the gate. */
    private fun deliverable(p: SalvoProcState): Int? {
        if (p.running || p.dead) {
            return null
        }
        val gate = p.gate ?: return if (p.queue.isEmpty()) null else 0
        val at = p.queue.indexOfFirst { it is SalvoEntry.Reply && it.slot == gate }
        return if (at < 0) null else at
    }

    /** True when nothing can ever run again without outside input. */
    private fun idle(): Boolean = active == 0 && procs.all { deliverable(it) == null }

    /** The idle-with-parked-gates report (SUPERVISION.md S-3). */
    private fun reportDeadlock(): Nothing {
        val parked =
            procs.withIndex().filter { it.value.gate != null && !it.value.dead }.map { "process ${it.index}" }
        System.err.println(
            "salvo: deadlock: all processes idle while main waits" +
                if (parked.isEmpty()) "" else " (parked gates: ${parked.joinToString(", ")})",
        )
        kotlin.system.exitProcess(1)
    }

    private fun worker(pool: Int) {
        while (true) {
            var pid = -1
            var entry: SalvoEntry? = null
            var body: SalvoProcess? = null
            lock.withLock {
                while (true) {
                    val job =
                        procs.withIndex().firstNotNullOfOrNull { (i, p) ->
                            if (p.pool != pool) {
                                null
                            } else {
                                deliverable(p)?.let { Triple(i, it, p) }
                            }
                        }
                    if (job != null) {
                        val (i, at, p) = job
                        pid = i
                        entry = p.queue.removeAt(at)
                        if (entry is SalvoEntry.User) {
                            p.userLen -= 1
                        }
                        val e = entry
                        if (e is SalvoEntry.Reply && p.gate == e.slot) {
                            p.gate = null
                        }
                        body = p.body
                        p.body = null
                        p.running = true
                        active += 1
                        cv.signalAll() // a user entry left the queue
                        break
                    }
                    cv.await()
                }
            }
            val ctx = SalvoCtx(pid)
            var fault: String? = null
            try {
                when (val e = entry) {
                    is SalvoEntry.User -> body!!.handle(ctx, e.msg)
                    is SalvoEntry.Reply -> body!!.resume(ctx, e.slot, e.value)
                    null -> {}
                }
            } catch (t: Throwable) {
                fault = t.message ?: t.javaClass.simpleName
            }
            lock.withLock {
                val p = procs[pid]
                p.running = false
                active -= 1
                if (fault == null) {
                    p.body = body
                } else {
                    p.dead = true
                    p.queue.clear()
                    p.userLen = 0
                    p.gate = null
                    val watchers = p.watchers.toList()
                    p.watchers.clear()
                    for (w in watchers) {
                        deliverReply(w, "fault: $fault")
                    }
                }
                cv.signalAll()
            }
        }
    }
}

internal sealed class SalvoTarget

internal class SalvoTargetProc(val pid: Int) : SalvoTarget()

internal class SalvoTargetWaiter(val wid: Int) : SalvoTarget()

/**
 * A one-shot reply capability. `send` delivers exactly once — the
 * guarantee is the checker's; the runtime only enqueues.
 */
class SalvoReply internal constructor(internal val target: SalvoTarget, internal val slot: Long) {
    fun send(value: Any?) = SalvoSched.sendReply(this, value)
}
